response:
**Gates before launch.** I run these gates in order and stop at the first one that fails.

1. I check that `spe/predictions/r04.yaml` and `spe/plans/r04.md` are in the last commit and unchanged since then.
2. I count the entries in `spe/evals/tasks/answers.json`. The plan says 50 tickets, but the eval set has 40. If the file has 40 entries, I halt and ask you which number is right. I do not quietly run a smaller round.
3. I run the grader selftest. `answers.json` fed back as predictions must score 1.0 on category and priority. An empty file must score 0 or exit with an error. A file with every label shifted by one class must score 0. I also run `judge.md` on 2 replies that should pass and 2 that should fail.
4. I regrade round 3's saved outputs with today's `grade.py` as a control. Any change from the round 3 numbers is a grader change. I log it in `spe/failures.md` with the old and new numbers side by side.
5. I do a dry run with `args.only` set to 3 cells and `trials: 1`, and I check that every result passes its schema and reports a cost.
6. I use the dry run cost to set `estTrialUsd` and `estJudgeUsd`. Suppose 500 trials plus 500 judge calls would cross $40 minus the dry run spend. Then I halt and ask you, because otherwise the cap would skip trials and break the 5-per-cell design.
7. I commit the script as `SPE r04 evaluate (harness)` and launch it with `spendCapUsd` set to $40 minus the dry run spend.

Some details were missing, so I chose these defaults:
- **Ticket text:** the launcher passes ticket bodies in `args.tickets`, so trials never open `spe/evals/`.
- **Running the triage agent:** each config's run command arrives in `args.configs`, with `{ticket_file}` and `{out_file}` placeholders.
- **grade.py:** it reads JSONL rows and prints one JSON result per row, keyed by the `trial` field.

```js
export const meta = {
  name: 'spe-triage-round',
  description: 'SPE eval round for the triage agent. Each config runs on each ticket for N trials. grade.py checks labels, an Opus judge scores reply tone, split cells get top-up trials, transcripts are audited for peeks, and the run ends with failure analysis and a completeness critic.',
  phases: ['Trials', 'Grade', 'Judge', 'Top-up', 'Audit', 'Synthesis'],
}

// Launch args, built by the launcher outside this script:
// {
//   round: 4,
//   configs: {
//     B:  { cmd: 'python triage/run.py --config triage/configs/B.yaml --ticket {ticket_file} --out {out_file}' },
//     C2: { cmd: 'python triage/run.py --config triage/configs/C2.yaml --ticket {ticket_file} --out {out_file}' },
//   },
//   tickets: [{ id: 'T-001', body: '...' }],    // id and body only, never labels
//   expectedTickets: 50,
//   trials: 5,
//   spendCapUsd: 40,                           // minus the dry run spend
//   estTrialUsd: <measured in dry run>,
//   estJudgeUsd: <measured in dry run>,
//   allowedPaths: ['triage/'],
//   transcriptDir: '<trial transcript folder>',
//   only: ['B:T-007', 'C2:T-007', 'B:T-031'],  // dry run only
// }

const ROUND = Number(args.round ?? 4)
const RR = `r${String(ROUND).padStart(2, '0')}`
const CONFIGS = ['B', 'C2']
const TRIALS = args.trials ?? 5
const EXPECTED_TICKETS = args.expectedTickets ?? 50
const CAP_USD = args.spendCapUsd ?? 40
const EST_TRIAL_USD = args.estTrialUsd
const EST_JUDGE_USD = args.estJudgeUsd
const TOPUP_PER_CELL = args.topUpPerCell ?? 3
const TOPUP_MAX_TRIALS = args.topUpMaxTrials ?? 60
const MAX_AGENTS = args.maxAgents ?? 1300
const DRIVER_MODEL = args.driverModel ?? 'opus'
const GRADER_MODEL = args.graderModel ?? 'opus'
const JUDGE_MODEL = 'opus'
const ALLOWED = args.allowedPaths ?? ['triage/']
const FORBIDDEN = ['spe/evals/', 'spe/predictions/', 'spe/plans/', 'spe/spec/', 'spe/prediction-log.md', 'spe/failures.md']
const FORBIDDEN_NAMES = /answers\.json|grade\.py|judge\.md|r\d\d(-draft)?\.yaml/
const GRADE_CMD = args.gradeCmd ?? 'python spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --pred {pred_file} --json'
const TMP = `/tmp/spe-${RR}`

// ---------- input checks ----------
function fail(msg) {
  log(`HALT: ${msg}`)
  throw new Error(msg)
}

if (!args.configs) fail('args.configs is required, with a cmd for each config')
const givenConfigs = Object.keys(args.configs).sort().join(',')
if (givenConfigs !== [...CONFIGS].sort().join(',')) fail(`configs are ${givenConfigs}, but the approved plan names ${CONFIGS.join(', ')}`)
for (const c of CONFIGS) {
  const cmd = args.configs[c].cmd ?? ''
  if (!cmd.includes('{ticket_file}') || !cmd.includes('{out_file}')) fail(`config ${c} cmd needs {ticket_file} and {out_file}`)
}
if (!Array.isArray(args.tickets) || args.tickets.length === 0) fail('args.tickets is required')
if (!args.only && args.tickets.length !== EXPECTED_TICKETS) fail(`got ${args.tickets.length} tickets, the approved plan says ${EXPECTED_TICKETS}`)
for (const t of args.tickets) {
  const extra = Object.keys(t).filter(k => k !== 'id' && k !== 'body')
  if (extra.length) fail(`ticket ${t.id} carries ${extra.join(', ')}. Tickets must hold id and body only.`)
}
if (!(EST_TRIAL_USD > 0) || !(EST_JUDGE_USD > 0)) fail('estTrialUsd and estJudgeUsd must come from the dry run')

// ---------- budget ----------
// The spend cap covers triage API spend (reported per trial) plus the judge estimate per call.
// Driver, grader, and analysis agents are limited by the agent cap.
const budget = { spentUsd: 0, reservedUsd: 0, agents: 0, skipped: [] }

function reserve(kind, key, estUsd) {
  if (budget.agents + 1 > MAX_AGENTS) {
    budget.skipped.push({ kind, key, reason: `agent cap ${MAX_AGENTS}` })
    log(`SKIP ${kind} ${key}: agent cap reached`)
    return false
  }
  if (budget.spentUsd + budget.reservedUsd + estUsd > CAP_USD) {
    budget.skipped.push({ kind, key, reason: `spend cap $${CAP_USD}` })
    log(`SKIP ${kind} ${key}: spend cap would be crossed`)
    return false
  }
  budget.agents += 1
  budget.reservedUsd += estUsd
  return true
}

function settle(estUsd, actualUsd) {
  budget.reservedUsd -= estUsd
  budget.spentUsd += Number.isFinite(actualUsd) ? actualUsd : estUsd
}

// ---------- schemas ----------
const num = { type: 'number' }
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['status', 'paths_read', 'commands_run'],
  properties: {
    status: { type: 'string', enum: ['ok', 'harness_error'] },
    error: { type: 'string' },
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    metrics: {
      type: 'object',
      required: ['runtime_s', 'tool_calls', 'tool_errors', 'input_tokens', 'output_tokens', 'cost_usd'],
      properties: { runtime_s: num, tool_calls: num, tool_errors: num, input_tokens: num, output_tokens: num, cost_usd: num },
    },
    paths_read: { type: 'array', items: { type: 'string' } },
    commands_run: { type: 'array', items: { type: 'string' } },
  },
}

const GRADE_SCHEMA = {
  type: 'object',
  required: ['exit_code', 'rows'],
  properties: {
    exit_code: { type: 'integer' },
    stderr: { type: 'string' },
    rows: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'category_ok', 'priority_ok'],
        properties: { trial: { type: 'integer' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } },
      },
    },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['score', 'pass', 'reason'],
  properties: {
    score: { type: 'integer', minimum: 1, maximum: 5 },
    pass: { type: 'boolean' },
    reason: { type: 'string' },
  },
}

const AUDIT_SCHEMA = {
  type: 'object',
  required: ['scanned_files', 'peeks'],
  properties: {
    scanned_files: { type: 'integer' },
    peeks: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_key', 'evidence'],
        properties: { trial_key: { type: 'string' }, evidence: { type: 'string' } },
      },
    },
  },
}

const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['failure_types', 'label_or_grader_suspects'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'existing_id', 'count_by_config', 'example_keys', 'what', 'how_to_spot', 'fix'],
        properties: {
          name: { type: 'string' },
          kind: { type: 'string', enum: ['agent', 'grader', 'harness', 'task'] },
          existing_id: { type: ['string', 'null'] },
          count_by_config: { type: 'object' },
          example_keys: { type: 'array', items: { type: 'string' } },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          fix: { type: 'string' },
        },
      },
    },
    label_or_grader_suspects: {
      type: 'array',
      items: { type: 'object', properties: { ticket_id: { type: 'string' }, why: { type: 'string' } } },
    },
  },
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps', 'halt_reasons'],
  properties: {
    complete: { type: 'boolean' },
    gaps: {
      type: 'array',
      items: { type: 'object', properties: { issue: { type: 'string' }, severity: { type: 'string' }, evidence: { type: 'string' } } },
    },
    halt_reasons: { type: 'array', items: { type: 'string' } },
  },
}

// ---------- helpers ----------
function fill(template, vars) {
  return Object.entries(vars).reduce((s, [k, v]) => s.split(`{${k}}`).join(v), template)
}

function peeked(r) {
  const trail = [...(r?.paths_read ?? []), ...(r?.commands_run ?? [])].join('\n')
  return FORBIDDEN.some(p => trail.includes(p)) || FORBIDDEN_NAMES.test(trail)
}

const both = t => t.category_ok === true && t.priority_ok === true
const mean = xs => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null)
const rate = (xs, f) => (xs.length ? xs.filter(f).length / xs.length : null)

// ---------- cells ----------
let cells = []
for (const config of CONFIGS) {
  for (const ticket of args.tickets) {
    cells.push({ config, ticket, key: `${config}:${ticket.id}`, trials: [], nextTrial: 1, graderErrors: [], topUpCount: 0 })
  }
}
if (args.only) {
  const only = new Set(args.only)
  cells = cells.filter(c => only.has(c.key))
  if (cells.length === 0) fail('args.only matched no cells')
  log(`DRY RUN: ${cells.length} cells`)
}

// ---------- prompts ----------
function trialPrompt(cell, trialNo) {
  const dir = `${TMP}/${cell.config}/${cell.ticket.id}/t${trialNo}`
  const ticketFile = `${dir}/ticket.txt`
  const outFile = `${dir}/out.json`
  return [
    'You are a test driver for the "triage" support agent. You run it once on one ticket and report what it produced. You do not judge, fix, or rerun its output.',
    '',
    'Rules:',
    `- You may read only these paths: ${ALLOWED.join(', ')}, and files you create under ${dir}.`,
    `- Do not open, list, search, or print anything under ${FORBIDDEN.join(', ')}. Touching those paths voids this trial.`,
    '- Do not edit any file in the repository. Do not run git.',
    '',
    'Steps:',
    `1. Create ${dir} and write the ticket below to ${ticketFile}, exactly as given.`,
    `2. Run this command once: ${fill(args.configs[cell.config].cmd, { ticket_file: ticketFile, out_file: outFile })}`,
    `3. Read ${outFile}. It holds the agent's JSON output and its usage record.`,
    '4. Copy label.category, label.priority, and reply verbatim from the agent output. Do not correct them. Take runtime_s, tool_calls, tool_errors, input_tokens, output_tokens, and cost_usd from the usage record.',
    '5. If the command fails to start, times out, or hits a rate limit, return status "harness_error" with the error text. If the agent ran but gave a bad or empty label, return status "ok" with the label as it gave it.',
    '6. List every file path you read in paths_read and every command you ran in commands_run.',
    '',
    `Ticket ${cell.ticket.id}:`,
    '<ticket>',
    cell.ticket.body,
    '</ticket>',
  ].join('\n')
}

function gradePrompt(rows, predFile) {
  return [
    'You run the code grader on one batch of triage outputs. You do not grade anything yourself.',
    '',
    `1. Write these rows to ${predFile}, one JSON object per line, exactly as given:`,
    ...rows.map(r => JSON.stringify(r)),
    `2. Run: ${fill(GRADE_CMD, { pred_file: predFile })}`,
    '3. For each input row, copy category_ok and priority_ok from the grader output, keyed by the trial field.',
    '4. Return the exit code. If it is not 0, return stderr and an empty rows list.',
    'Do not edit grade.py, answers.json, or any other repository file.',
  ].join('\n')
}

function judgePrompt(ticket, reply) {
  return [
    'Read spe/evals/graders/judge.md and apply its rubric to the draft reply below.',
    'You see one support ticket and one draft first reply. You are not told which system wrote it.',
    'Judge tone only, as judge.md defines it. Do not judge whether the category or priority is right.',
    'Return a score from 1 to 5, pass as judge.md defines it, and a one-sentence reason that quotes the reply.',
    'Do not edit any file.',
    '',
    '<ticket>',
    ticket.body,
    '</ticket>',
    '',
    '<reply>',
    reply,
    '</reply>',
  ].join('\n')
}

// ---------- stages ----------
async function runTrial(cell, trialNo, phaseName) {
  const key = `${cell.key}#${trialNo}`
  if (!reserve('trial', key, EST_TRIAL_USD)) return null
  let r
  try {
    r = await agent(trialPrompt(cell, trialNo), { label: key, phase: phaseName, schema: TRIAL_SCHEMA, model: DRIVER_MODEL })
  } catch (e) {
    r = { status: 'harness_error', error: String(e?.message ?? e), paths_read: [], commands_run: [] }
  }
  settle(EST_TRIAL_USD, r?.metrics?.cost_usd)
  const voided = peeked(r)
  if (voided) log(`VOID ${key}: trial touched a forbidden path`)
  return { ...r, trialNo, topUp: phaseName === 'Top-up', voided }
}

function trialsStage(phaseName, countOf) {
  return async cell => {
    const nums = Array.from({ length: countOf(cell) }, () => cell.nextTrial++)
    const out = await parallel(nums.map(n => () => runTrial(cell, n, phaseName)))
    cell.trials.push(...out.filter(Boolean))
    return cell
  }
}

async function gradeStage(cell) {
  const todo = cell.trials.filter(t => t.status === 'ok' && !t.voided && t.category_ok === undefined)
  if (todo.length === 0) return cell
  if (!reserve('grade', cell.key, 0)) return cell
  const predFile = `${TMP}/grade/${cell.config}-${cell.ticket.id}-from-t${todo[0].trialNo}.jsonl`
  const rows = todo.map(t => ({
    ticket_id: cell.ticket.id,
    trial: t.trialNo,
    label: { category: t.label?.category ?? '', priority: t.label?.priority ?? '' },
  }))
  let g
  try {
    g = await agent(gradePrompt(rows, predFile), { label: `grade ${cell.key}`, phase: 'Grade', schema: GRADE_SCHEMA, model: GRADER_MODEL })
  } catch (e) {
    cell.graderErrors.push(String(e?.message ?? e))
    log(`GRADER ERROR ${cell.key}: agent failed`)
    return cell
  }
  if (g.exit_code !== 0) {
    cell.graderErrors.push(g.stderr ?? `exit ${g.exit_code}`)
    log(`GRADER ERROR ${cell.key}: exit ${g.exit_code}`)
    return cell
  }
  for (const t of todo) {
    const row = g.rows.find(x => x.trial === t.trialNo)
    if (!row) {
      cell.graderErrors.push(`no grader row for trial ${t.trialNo}`)
      continue
    }
    t.category_ok = row.category_ok
    t.priority_ok = row.priority_ok
  }
  return cell
}

async function judgeStage(cell) {
  const todo = cell.trials.filter(t => t.status === 'ok' && !t.voided && t.tone === undefined)
  await parallel(todo.map(t => async () => {
    const key = `${cell.key}#${t.trialNo}`
    // Code check first. An empty reply fails tone without a judge call.
    if (!(t.reply ?? '').trim()) {
      t.tone = { score: 1, pass: false, reason: 'empty reply (code check)' }
      return
    }
    if (!reserve('judge', key, EST_JUDGE_USD)) return
    try {
      t.tone = await agent(judgePrompt(cell.ticket, t.reply), { label: `judge ${key}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL })
    } catch (e) {
      t.toneError = String(e?.message ?? e)
    }
    settle(EST_JUDGE_USD)
  }))
  return cell
}

// ---------- Trials, Grade, Judge ----------
phase('Trials')
log(`${RR}: ${cells.length} cells x ${TRIALS} trials, configs ${CONFIGS.join(', ')}, cap $${CAP_USD}`)
await pipeline(cells, trialsStage('Trials', () => TRIALS), gradeStage, judgeStage)
log(`After main trials: spent $${budget.spentUsd.toFixed(2)}, agents ${budget.agents}, skipped ${budget.skipped.length}`)

// ---------- Top-up ----------
phase('Top-up')
const split = cells
  .map(c => {
    const g = c.trials.filter(t => !t.topUp && t.category_ok !== undefined)
    return { c, n: g.length, p: g.filter(both).length }
  })
  .filter(x => x.p > 0 && x.p < x.n)
  .sort((a, b) => Math.abs(a.p / a.n - 0.5) - Math.abs(b.p / b.n - 0.5))
let topUpLeft = TOPUP_MAX_TRIALS
for (const x of split) {
  x.c.topUpCount = Math.min(TOPUP_PER_CELL, topUpLeft)
  topUpLeft -= x.c.topUpCount
}
const topUpCells = split.map(x => x.c).filter(c => c.topUpCount > 0)
const splitNoTopUp = split.map(x => x.c.key).filter(k => !topUpCells.some(c => c.key === k))
log(`Top-up: ${split.length} split cells, ${topUpCells.length} get extra trials, ${TOPUP_MAX_TRIALS - topUpLeft} trials planned`)
if (splitNoTopUp.length) log(`Top-up cap left ${splitNoTopUp.length} split cells without extra trials`)
if (topUpCells.length) await pipeline(topUpCells, trialsStage('Top-up', c => c.topUpCount), gradeStage, judgeStage)

// ---------- Audit ----------
phase('Audit')
let audit = null
if (args.transcriptDir && reserve('audit', 'transcripts', 0)) {
  audit = await agent([
    `Scan the trial transcripts under ${args.transcriptDir} for answer-key peeks.`,
    'Look only at tool-call inputs (file reads, searches, shell commands). Ignore prompt text, because every trial prompt names the forbidden paths.',
    `A peek is any tool call that touches ${FORBIDDEN.join(', ')}, or a file named answers.json, grade.py, judge.md, or a round prediction yaml.`,
    'Trial transcripts carry labels shaped like "B:T-001#3". Return each peeking trial by that label, with the tool call as evidence.',
    'Do not edit any file.',
  ].join('\n'), { label: 'transcript audit', phase: 'Audit', schema: AUDIT_SCHEMA, model: GRADER_MODEL })
  for (const p of audit.peeks) {
    const [cellKey, n] = p.trial_key.split('#')
    const t = cells.find(c => c.key === cellKey)?.trials.find(x => x.trialNo === Number(n))
    if (t && !t.voided) {
      t.voided = true
      t.voidEvidence = p.evidence
      log(`VOID ${p.trial_key}: transcript audit found ${p.evidence}`)
    }
  }
} else {
  log('No transcriptDir given. Peek check used self-reported trails only. The close-out must scan transcripts.')
}

// ---------- Synthesis ----------
phase('Synthesis')

function summarize(config, includeTopUp) {
  const cs = cells.filter(c => c.config === config)
  const all = cs.flatMap(c => c.trials.filter(t => includeTopUp || !t.topUp))
  const done = all.filter(t => t.status === 'ok' && !t.voided && t.category_ok !== undefined)
  const judged = done.filter(t => t.tone)
  const m = k => mean(done.map(t => t.metrics?.[k]).filter(Number.isFinite))
  const cellRates = cs.map(c => {
    const g = c.trials.filter(t => !t.topUp && t.status === 'ok' && !t.voided && t.category_ok !== undefined)
    return { n: g.length, p: g.filter(both).length }
  }).filter(x => x.n > 0)
  return {
    ran: all.length,
    completed: done.length,
    voided: all.filter(t => t.voided).length,
    harness_errors: all.filter(t => t.status === 'harness_error').length,
    ungraded: all.filter(t => t.status === 'ok' && !t.voided && t.category_ok === undefined).length,
    category_acc: rate(done, t => t.category_ok),
    priority_acc: rate(done, t => t.priority_ok),
    both_acc: rate(done, both),
    tone_pass: rate(judged, t => t.tone.pass),
    tone_score_mean: mean(judged.map(t => t.tone.score)),
    unjudged: done.length - judged.length,
    runtime_s_mean: m('runtime_s'),
    tool_calls_mean: m('tool_calls'),
    tool_errors_mean: m('tool_errors'),
    tokens_mean: mean(done.map(t => (t.metrics?.input_tokens ?? 0) + (t.metrics?.output_tokens ?? 0))),
    triage_cost_usd: all.reduce((s, t) => s + (Number.isFinite(t.metrics?.cost_usd) ? t.metrics.cost_usd : 0), 0),
    cells_all_pass: cellRates.filter(x => x.p === x.n).length,
    cells_split: cellRates.filter(x => x.p > 0 && x.p < x.n).length,
    cells_all_fail: cellRates.filter(x => x.p === 0).length,
  }
}

// The predicted numbers use only the pre-registered trials. Top-up numbers are reported separately.
const summary = {}
const accounting = {}
for (const config of CONFIGS) {
  summary[config] = { preregistered: summarize(config, false), with_topup: summarize(config, true) }
  const cs = cells.filter(c => c.config === config)
  const planned = cs.length * TRIALS
  const ran = cs.flatMap(c => c.trials.filter(t => !t.topUp)).length
  const skippedTrials = budget.skipped.filter(s => s.kind === 'trial' && s.key.startsWith(`${config}:`) && Number(s.key.split('#')[1]) <= TRIALS).length
  accounting[config] = { planned, ran, skipped: skippedTrials, unaccounted: planned - ran - skippedTrials }
}
const graderErrors = cells.filter(c => c.graderErrors.length).map(c => ({ cell: c.key, errors: c.graderErrors }))
const voided = cells.flatMap(c => c.trials.filter(t => t.voided).map(t => ({ key: `${c.key}#${t.trialNo}`, evidence: t.voidEvidence ?? 'self-reported trail' })))
if (voided.length) log(`HALT CONDITION: ${voided.length} trials touched answer-key paths`)
if (graderErrors.length) log(`HALT CONDITION: grader errors in ${graderErrors.length} cells`)
if (budget.skipped.length) log(`HALT CONDITION: ${budget.skipped.length} items skipped at a cap`)

const failed = cells.flatMap(c => c.trials
  .filter(t => t.status !== 'ok' || t.voided || t.category_ok === false || t.priority_ok === false || t.tone?.pass === false)
  .map(t => ({
    key: `${c.key}#${t.trialNo}`,
    config: c.config,
    ticket_id: c.ticket.id,
    top_up: t.topUp,
    status: t.status,
    error: t.error,
    voided: t.voided,
    label: t.label,
    category_ok: t.category_ok,
    priority_ok: t.priority_ok,
    tone: t.tone,
    tool_errors: t.metrics?.tool_errors,
  })))

let failureAnalysis = null
if (failed.length && reserve('analysis', 'failures', 0)) {
  failureAnalysis = await agent([
    'Group these failed triage trials into failure types.',
    'Read spe/failures.md and reuse an existing F-number when a type matches. Use null for a new type.',
    'You may read spe/evals/tasks/answers.json to see reference labels. Do not read spe/predictions/. Do not edit any file.',
    'For each type give the name, kind (agent, grader, harness, or task), existing F-number, count per config, up to 5 example keys, What, How to spot it, and a proposed Fix.',
    'List separately any ticket where you think the reference label or the grader is wrong, with the reason.',
